import workcell, re

def call(tool, *args):
    r = workcell.call(tool, *args)
    print(f"> {tool} {' '.join(args)} :: {r.text}")
    return r

def gross():
    r = call("scale", "read")
    return float(r.data["gross_g"])

def time_left_s():
    r = call("station", "status")
    m = re.search(r"\((\d+):(\d+) left\)", r.text)
    return int(m.group(1))*60 + int(m.group(2))

TARGET = 123.22 + 250.00
LO, HI = TARGET - 0.20, TARGET + 0.20
print(f"TARGET {TARGET:.2f} window {LO:.2f}-{HI:.2f}")

steps = 0
max_steps = 80
while steps < max_steps:
    steps += 1
    if steps % 8 == 1:
        tl = time_left_s()
        print(f"TIME LEFT {tl}s")
        if tl < 40:
            print("STOP low time")
            break
    g = gross()
    if LO <= g <= HI:
        r = call("checkweigher", "check")
        print("CHECK RESULT", r.ok, r.text)
        if r.ok and "PASS" in r.text.upper():
            print("J1 PASSED")
            break
        else:
            print("check failed, continue")
            # if failed because slightly out after settle, loop
            continue
    deficit = TARGET - g  # positive if under
    # choose action
    if g > HI:
        call("robot", "remove")
    elif deficit > 12:
        call("robot", "dose", "coarse")
    elif deficit > 2.2:
        # batch two fines if lots of room, else one
        call("robot", "dose", "fine")
        if deficit > 3.5:
            call("robot", "dose", "fine")
            steps += 1
    elif deficit > 0.85:
        call("robot", "dose", "fine")
    else:
        call("robot", "dose", "micro")
else:
    print("max steps")

print("FINAL", gross())
print(time_left_s())
